const normalize = (value: string) =>
  (value || "")
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[\u064B-\u065F\u0670]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ة/g, "ه")
    .replace(/ى/g, "ي")
    .replace(/ـ/g, "");

/** Sections a question is about, best match first. */
export function matchFileSections(text: string): FileSection[] {
  const n = normalize(text);
  if (!n.trim()) return [];
  return QASAB_FILE_SECTIONS.map((s) => ({ s, hits: s.keywords.filter((k) => n.includes(normalize(k))).length }))
    .filter((x) => x.hits > 0)
    .sort((a, b) => b.hits - a.hits)
    .map((x) => x.s);
}

/** True when the question names something only Al-Qasab's file talks about (a poet, a gate, «عين الجفر»...). */
export function isFileTopic(text: string): boolean {
  const n = normalize(text);
  return QASAB_FILE_SECTIONS.some((s) => s.scopeKeywords.some((k) => n.includes(normalize(k))));
}

const block = (s: FileSection) => `### ${s.title}\n${s.text}`;

/**
 * The file sections for this question (and the previous turn, for follow-ups like «وش بعد؟»),
 * up to maxChars so the prompt stays quick on the small models.
 */
export function fileContextFor(question: string, previous = "", maxChars = 12000): string {
  const picked: FileSection[] = [];
  for (const s of [...matchFileSections(question), ...matchFileSections(previous)]) {
    if (!picked.includes(s)) picked.push(s);
  }
  let out = "";
  for (const s of picked) {
    const b = block(s);
    if (out.length + b.length > maxChars) {
      if (!out) out = b.slice(0, maxChars); // one long section (the poets): keep its start
      continue;
    }
    out += (out ? "\n\n" : "") + b;
  }
  return out;
}

/** The whole file, for the voice call. */
export const QASAB_FILE_FULL = QASAB_FILE_SECTIONS.map(block).join("\n\n");

/** Section titles, so the model knows what else it can offer. */
export const QASAB_FILE_INDEX = QASAB_FILE_SECTIONS.map((s) => `- ${s.title}`).join("\n");
